p.extended-example:
typedef union Information_Fields
{
    struct
    {
        char *load_address;
        char *execute_address;
    } load_exec;
    struct
    {
        int part_1;
        int part_2;
    } date_type;
} Information_Fields;

typedef struct provider_context provider_context;   /* opaque */
typedef unsigned int provider_offset;               /* byte offset on the medium */

_kernel_oserror *provider_open(provider_context **ctx);
void             provider_close(provider_context *ctx);
provider_offset  provider_size(provider_context *ctx);
_kernel_oserror *provider_read(provider_context *ctx,
                               provider_offset offset,
                               void *buffer,
                               unsigned int length);

void fsdata_to_riscos(const fsdata_descriptor *desc, fsdata_catalogue *cat)
{
    cat->object_type = desc->is_directory ? ObjectType_Directory
                                           : ObjectType_File;
    cat->length = desc->length;

    if (desc->has_filetype)
    {
        /* Filetyped object: load = 0xFFFttthh, exec = low 4 bytes of date */
        cat->load_address = 0xFFF00000u
                          | ((desc->filetype & 0xFFFu) << 8)
                          | (desc->datestamp_high & 0xFFu);
        cat->exec_address = desc->datestamp_low;
    }
    else
    {
        cat->load_address = desc->load_address;
        cat->exec_address = desc->exec_address;
    }

    cat->attributes = 0;
    if (desc->owner_read)   cat->attributes |= Attribute_OwnerRead;
    if (desc->owner_write)  cat->attributes |= Attribute_OwnerWrite;
    if (desc->public_read)  cat->attributes |= Attribute_PublicRead;
    if (desc->public_write) cat->attributes |= Attribute_PublicWrite;
    if (desc->locked)       cat->attributes |= Attribute_Locked;
}

case FSEntry_File_Reason_ReadCatalogueInformation:
{
    fsdata_descriptor desc;
    fsdata_catalogue cat;

    err = fsdata_find(parm->name, &desc);
    if (err == err_NotFound)             /* your data layer's "no such object" */
    {
        parm->reason = (FSEntry_File_Reason) ObjectType_NotFound;   /* R0 */
        err = NULL;
        break;
    }
    if (err != NULL) break;

    fsdata_to_riscos(&desc, &cat);
    parm->reason = (FSEntry_File_Reason) cat.object_type;           /* R0 */
    parm->info.load_exec.load_address = (char *) cat.load_address;  /* R2 */
    parm->info.load_exec.execute_address = (char *) cat.exec_address; /* R3 */
    parm->extras.info.length = cat.length;                           /* R4 */
    parm->extras.info.attributes = cat.attributes;                   /* R5 */
    break;
}

